    """
    encode_shift fonksiyonu ile kodlanmış string'i girdi olarak alır. Çözülmüş string'i döndürür.
    """
    return "".join([chr(((ord(ch) - 5 - ord("a")) % 26) + ord("a")) for ch in s])
