def prime_length(string):
    """Bir string alan ve string uzunluğu asal sayı ise True, 
    değilse False döndüren bir fonksiyon yaz
    Örnekler
    prime_length('Hello') == True
    prime_length('abcdcba') == True
    prime_length('kittens') == True
    prime_length('orange') == False
    """
    def is_prime(n):
        """Asal sayı olup olmadığını kontrol eden bir fonksiyon"""
        if n <= 1:
            return False
        for i in range(2, int(n**0.5) + 1):
            if n % i == 0:
                return False
        return True

    return is_prime(len(string))
