def f(n):
    """ Define a function that takes n as an argument and returns a list of length n filled with the value at index i, which is the factorial of i if i is even, or the sum of numbers from 1 to i if i is odd. Start with i = 1.

    This translation maintains the original meaning and structure of the Turkish code, while using English syntax and terminology.
    """
    result = []
    for i in range(1, n + 1):
        if i % 2 == 0:
            result.append(i * factorial(i))
        else:
            result.append(sum(range(1, i + 1)))
    return result
