def histogram(test):
    """Given a string with separated small letters, return a dictionary containing the most frequent letter and its count. If multiple letters have the same count, return all of them.

    Example:
    histogram('a b c') == {'a': 1, 'b': 1, 'c': 1}
    histogram('a b b a') == {'a': 2, 'b': 2}
    histogram('a b c a b') == {'a': 2, 'b': 2}
    histogram('b b b b a') == {'b': 4}
    histogram('') == {}
    """
    if not test:
        return {}

    letter_counts = {}
    for letter in test:
        if letter in letter_counts:
            letter_counts[letter] += 1
        else:
            letter_counts[letter] = 1

    max_count = max(letter_counts.values())
    most_frequent_letters = [letter for letter, count in letter_counts.items() if count == max_count]

    return dict(zip(most_frequent_letters, [max_count] * len(most_frequent_letters)))
```

